sig:
enum class perms : unsigned {
    none = 0,
    owner_read = 0400, owner_write = 0200, owner_exec = 0100,
    group_read = 0040, others_read = 0004, /* ... */
    all = 0777
};

example:
fs::path p = "archive.tar.gz";
std::cout << p.extension().string() << "\n";  // .gz
std::cout << fs::path("README").extension().empty();  // 1

fs::path p = "build/app.exe";
std::cout << p.stem().string() << "\n";   // app
fs::path o = p.parent_path() / (p.stem().string() + ".o");

fs::path p = "/home/user/a.txt";
std::cout << p.parent_path().string() << "\n";   // /home/user
std::cout << fs::path("a.txt").parent_path().empty();  // 1

fs::path a = "C:/Windows";
fs::path b = "/temp";
std::cout << a.is_absolute() << " " << b.is_absolute();  // Windows 下 1 0

std::error_code ec;
if (!fs::exists("config.ini", ec) && ec)
    std::cout << "查不到，错误码 " << ec.value() << "\n";

if (fs::is_directory("logs"))
    std::cout << "是目录\n";
else
    std::cout << "不是目录或不存在\n";

if (fs::is_directory(p) && fs::is_empty(p))
    std::cout << "空目录\n";
if (fs::is_regular_file(p) && fs::is_empty(p))
    std::cout << "0 字节文件\n";

if (!fs::create_directory("out"))     // 已存在时返回 false
    std::cout << "已存在\n";
fs::create_directories("out/a/b");    // 多层要用这个

fs::create_directories("build/logs/2026");
bool created = fs::create_directories("build");  // 已存在，false
std::cout << created << "\n";

std::error_code ec;
bool ok = fs::remove("a.txt", ec);   // 不存在时 ok=false，不算错误
std::cout << ok << " " << ec.value() << "\n";

fs::rename("a.tmp", "a.txt");        // 同目录改名
fs::create_directories("build");
fs::rename("out", "build/out");       // 移动目录

sig:
enum class copy_options {
    none, skip_existing, overwrite_existing, update_existing,
    recursive, copy_symlinks, skip_symlinks,
    directories_only, create_symlinks, create_hard_links
};

example:
fs::create_directories("backup");
bool ok = fs::copy_file("a.bin", "backup/a.bin",
                        fs::copy_options::overwrite_existing);

auto t = fs::last_write_time("a.txt");
fs::last_write_time("a.txt", t + std::chrono::hours(24));  // 改成一天后
std::cout << (fs::last_write_time("a.txt") > t) << "\n";

fs::path dir = fs::temp_directory_path();
fs::path log = dir / "myapp.log";
std::ofstream out(log);   // 并发运行时同名文件会互相覆盖

std::error_code ec;
if (fs::equivalent("a.txt", "link_to_a.txt", ec))
    std::cout << "同一个文件\n";

fs::file_status st = fs::status("a.txt");
if (st.type() == fs::file_type::regular)
    std::cout << "普通文件\n";
else if (st.type() == fs::file_type::not_found)
    std::cout << "不存在\n";

fs::permissions("run.sh",
    fs::perms::owner_all | fs::perms::group_read,
    fs::perm_options::replace);

auto si = fs::space("D:/");
std::cout << si.capacity / (1024ull * 1024 * 1024) << " GB 总量，"
          << si.available / (1024ull * 1024 * 1024) << " GB 可用\n";

for (auto it = fs::recursive_directory_iterator("src");
     it != fs::recursive_directory_iterator(); ++it)
    std::cout << std::string(it.depth() * 2, ' ') << it->path().filename().string() << "\n";

for (auto it = fs::recursive_directory_iterator("src");
     it != fs::recursive_directory_iterator(); ++it) {
    if (it->path().filename() == ".git") it.disable_recursion_pending();
    else std::cout << it->path().string() << "\n";
}

fs::directory_iterator it("data", fs::directory_options::skip_permission_denied);
if (it.options() != fs::directory_options::none)
    std::cout << "已开启选项\n";
